// Builds the design system's bundle.js: the same components as src/, as one classic script that
// reads React from window.React and assigns window.Cendra. Output goes to dist-ds/bundle.js
import { build } from 'rolldown';

await build({
  input: new URL('../src/index.ts', import.meta.url).pathname,
  external: ['react'],
  transform: { jsx: { runtime: 'classic', pragma: 'React.createElement', pragmaFrag: 'React.Fragment' } },
  output: {
    file: new URL('../dist-ds/bundle.js', import.meta.url).pathname,
    format: 'iife',
    name: 'Cendra',
    globals: { react: 'React' },
    banner: '/* Cendrawasih UI components. Generated by scripts/build-ds-bundle.mjs from src/. Icon drawings from Lucide (https://lucide.dev), ISC License. */',
  },
  onwarn(warning, warn) {
    if (warning.code === 'MODULE_LEVEL_DIRECTIVE') return;
    warn(warning);
  },
});
